.ov-chip.system{background:#eff6ff;border-color:#dbeafe}.ov-chip.system b{color:#1d4ed8}
.ov-chip.sos{background:#fff1f2;border-color:#ffe4e6}.ov-chip.sos b{color:#be123c}
.ov-chip.radar{background:#fffbeb;border-color:#fef3c7}.ov-chip.radar b{color:#b45309}
.ov-chip.gps{background:#f0fdf4;border-color:#dcfce7}.ov-chip.gps b{color:#15803d}
.ov-chip.network{background:#f5f3ff;border-color:#ede9fe}.ov-chip.network b{color:#6d28d9}
.ov-chip.speed{background:#ecfeff;border-color:#cffafe}.ov-chip.speed b{color:#0e7490}
@media(max-width:900px){.ov{align-items:flex-start;flex-direction:column;gap:9px}.ov-brand{min-width:0}.ov-items{grid-template-columns:repeat(3,minmax(0,1fr));width:100%}}
@media(max-width:599px){.ov{padding:11px;border-radius:12px}.ov-title{font-size:18px}.ov-items{grid-template-columns:repeat(2,minmax(0,1fr))}.ov-chip{height:43px}}
/* Dynamic overview states */
.ov-chip[data-state="HỆ THỐNG ONLINE"],
.ov-chip[data-state="SOS BÌNH THƯỜNG"],
.ov-chip[data-state="KHÔNG PHÁT HIỆN"],
.ov-chip[data-state="4G ONLINE"],
.ov-chip[data-state="FIXED"],
.ov-chip[data-state="GPS_FIXED"]{
  background:#ecfdf3!important;border-color:#abefc6!important
}
.ov-chip[data-state="HỆ THỐNG ONLINE"] b,
.ov-chip[data-state="SOS BÌNH THƯỜNG"] b,
.ov-chip[data-state="KHÔNG PHÁT HIỆN"] b,
.ov-chip[data-state="4G ONLINE"] b,
.ov-chip[data-state="FIXED"] b,
.ov-chip[data-state="GPS_FIXED"] b{color:#067647!important}

.ov-chip[data-state="SOS ĐANG CHỜ"],
.ov-chip[data-state="MẤT KẾT NỐI"],
.ov-chip[data-state="4G OFFLINE"],
.ov-chip[data-state="GPS_FAULT"]{
  background:#fef3f2!important;border-color:#fecdca!important
}
.ov-chip[data-state="SOS ĐANG CHỜ"] b,
.ov-chip[data-state="MẤT KẾT NỐI"] b,
.ov-chip[data-state="4G OFFLINE"] b,
.ov-chip[data-state="GPS_FAULT"] b{color:#b42318!important}

.ov-chip[data-state="PHÁT HIỆN NGƯỜI"]{
  background:#fffaeb!important;border-color:#fedf89!important
}
.ov-chip[data-state="PHÁT HIỆN NGƯỜI"] b{color:#b54708!important}
